    let speech_permit = if spoken.is_empty() {
        None
    } else {
        match state.0.speech.try_reserve() {
            Ok(permit) => Some(permit),
            Err(_) => {
                return (
                    axum::http::StatusCode::SERVICE_UNAVAILABLE,
                    Json(json!({"detail":"speech worker is unavailable or busy"})),
                )
                    .into_response()
            }
        }
    };

